$auth = ($lines | Where-Object { $_ -match '^OBJECT_SERVICE_AUTH=' } | Select-Object -First 1) -replace '^OBJECT_SERVICE_AUTH=',''
$headers = @{ Authorization = $auth }
$now = Get-Date -Format "yyyy-MM-ddTHH:mm:ss"
$month = (Get-Date).AddMonths(-1).ToString("yyyy-MM-ddTHH:mm:ss")
function Get-Json($path) {
  try {
    $r = Invoke-WebRequest -Uri ($url + $path) -Headers $headers -UseBasicParsing -TimeoutSec 60
    Write-Output ("STATUS " + $r.StatusCode)
    Write-Output $r.Content
  } catch {
    $resp = $_.Exception.Response
    if ($resp) {
      $reader = New-Object System.IO.StreamReader($resp.GetResponseStream())
      Write-Output ("STATUS " + [int]$resp.StatusCode)
      Write-Output $reader.ReadToEnd()
    } else {
      Write-Output ("ERROR " + $_.Exception.Message)
    }
  }
  Write-Output "----"
}
